param([Parameter(Mandatory=$true)][string]$AfterRevision)
$env:TIDE_HIDDEN='1'
$ErrorActionPreference='Stop'
$taskRoot=(Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
$taskRevision=(git -C $taskRoot rev-parse --verify "$AfterRevision^{commit}").Trim()
if($LASTEXITCODE -or (git -C $taskRoot rev-parse HEAD).Trim() -ne $taskRevision){throw 'Expected committed after source at HEAD'}
git -C $taskRoot diff --quiet HEAD -- engine platform compiler tests bench/skinned bench/CMakeLists.txt cmake CMakeLists.txt CMakePresets.json
if($LASTEXITCODE){throw 'After source is dirty'}
$taskOutput=Join-Path $PSScriptRoot 'after-snapshot'
if(Test-Path -LiteralPath $taskOutput){throw 'After snapshot already exists'}
New-Item -ItemType Directory -Path $taskOutput | Out-Null
foreach($taskDirectory in @('fixture','generated','include/tide','sources')){New-Item -ItemType Directory -Path (Join-Path $taskOutput $taskDirectory) | Out-Null}
$taskCopies=[ordered]@{
    'build/skinned-cpu4-release/bin/bench_skinned.exe'='bench_skinned.exe';'build/skinned-cpu4-release/bin/bench_skinned.pdb'='bench_skinned.pdb';
    'build/skinned-cpu4-release/engine/tide.lib'='tide.lib';'build/skinned-cpu4-release/platform/tide_platform.lib'='tide_platform.lib';'build/skinned-cpu4-release/tide_font_bold.lib'='tide_font_bold.lib';
    'build/skinned-cpu4-release/bench/CMakeFiles/bench_skinned.dir/skinned/main.c.obj'='main.c.obj';
    'build/skinned-cpu4-release/bench/CMakeFiles/bench_skinned.dir/tide/bench_skinned/game.c.obj'='game.c.obj';
    'build/skinned-cpu4-release/bench/CMakeFiles/bench_skinned.dir/tide/bench_skinned/game_pack.c.obj'='game_pack.c.obj';
    'build/skinned-cpu4-release/bench/tide/bench_skinned/game.c'='generated/game.c';'build/skinned-cpu4-release/bench/tide/bench_skinned/game.h'='generated/game.h';'build/skinned-cpu4-release/bench/tide/bench_skinned/game_pack.c'='generated/game_pack.c';
    'bench/skinned/main.c'='fixture/main.c';'bench/skinned/game.tide'='fixture/game.tide';'bench/skinned/model.gltf'='fixture/model.gltf';'bench/skinned/generate.mjs'='fixture/generate.mjs';
    'engine/src/skinned.c'='sources/skinned.c';'engine/src/skinned_cache.h'='sources/skinned_cache.h';'engine/src/mesh.c'='sources/mesh.c';'platform/src/platform.c'='sources/platform.c';'platform/src/gpu_gl.c'='sources/gpu_gl.c';
    'build/skinned-cpu4-release/CMakeCache.txt'='sources/CMakeCache.txt';'build/skinned-cpu4-release/build.ninja'='sources/build.ninja'
}
foreach($taskCopy in $taskCopies.GetEnumerator()){Copy-Item -LiteralPath (Join-Path $taskRoot $taskCopy.Key) -Destination (Join-Path $taskOutput $taskCopy.Value)}
foreach($taskIncludeRoot in @('engine/include/tide','platform/include/tide')){Get-ChildItem -LiteralPath (Join-Path $taskRoot $taskIncludeRoot) -File | ForEach-Object {Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $taskOutput "include/tide/$($_.Name)")}}
$taskSourceFiles=@(git -C $taskRoot ls-files --cached --others --exclude-standard -- engine platform compiler tests bench/skinned bench/CMakeLists.txt cmake CMakeLists.txt CMakePresets.json | Sort-Object -Unique | ForEach-Object {
    $taskFile=Join-Path $taskRoot $_
    if(Test-Path -LiteralPath $taskFile -PathType Leaf){[ordered]@{path=$_;bytes=(Get-Item -LiteralPath $taskFile).Length;sha256=(Get-FileHash -LiteralPath $taskFile).Hash.ToLower()}}
})
$taskSourceFiles | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $taskOutput 'source-hashes.json') -Encoding utf8
Copy-Item -LiteralPath $PSCommandPath -Destination $taskOutput
foreach($taskPair in @('fixture/main.c','fixture/game.tide','fixture/model.gltf','generated/game.h','generated/game_pack.c')) {
    $taskBaseline=Join-Path $taskRoot "build/release/skinned-cpu3/after-snapshot/$taskPair"
    if((Get-FileHash -LiteralPath (Join-Path $taskOutput $taskPair)).Hash -ne (Get-FileHash -LiteralPath $taskBaseline).Hash){throw "Runtime-only workload/generated source differs: $taskPair"}
}
$taskBeforeGame=Join-Path $taskRoot 'build/release/skinned-cpu3/after-snapshot/generated/game.c'
$taskAfterGame=Join-Path $taskOutput 'generated/game.c'
$taskGeneratedComparison=[ordered]@{exception='Only the two #line file paths differ because the candidate uses an isolated build directory. Both raw files are retained. No other generated bytes may differ.';before=[ordered]@{};after=[ordered]@{}}
foreach($taskSide in @('before','after')) {
    $taskPath=if($taskSide -eq 'before'){$taskBeforeGame}else{$taskAfterGame}
    $taskBuildName=if($taskSide -eq 'before'){'release'}else{'skinned-cpu4-release'}
    $taskOriginalPath=$taskRoot.Replace('\','/')+"/build/$taskBuildName/bench/tide/bench_skinned/game.c"
    $taskPattern='(?m)^(#line [0-9]+ )"'+[regex]::Escape($taskOriginalPath)+'"$'
    $taskText=[IO.File]::ReadAllText($taskPath)
    $taskMatches=[regex]::Matches($taskText,$taskPattern)
    if($taskMatches.Count -ne 2){throw 'Expected exactly two generated #line paths'}
    $taskNormalized=[regex]::Replace($taskText,$taskPattern,'$1"<generated-game-c>"')
    $taskHash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($taskNormalized))).ToLower()
    $taskGeneratedComparison[$taskSide]=[ordered]@{raw_sha256=(Get-FileHash -LiteralPath $taskPath).Hash.ToLower();normalized_sha256=$taskHash;replaced_line_count=2;original_path=$taskOriginalPath}
    if($taskSide -eq 'before'){$taskBeforeNormalized=$taskNormalized}else{$taskAfterNormalized=$taskNormalized}
}
if($taskBeforeNormalized -cne $taskAfterNormalized){throw 'Generated runtime C differs beyond the two #line paths'}
$taskGeneratedComparison | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $taskOutput 'generated-source-comparison.json') -Encoding utf8
$taskFiles=@(Get-ChildItem -LiteralPath $taskOutput -File -Recurse | ForEach-Object {[ordered]@{path=[System.IO.Path]::GetRelativePath($taskOutput,$_.FullName).Replace('\','/');bytes=$_.Length;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower()}})
[ordered]@{source_revision=$taskRevision;preserved_at=(Get-Date).ToUniversalTime().ToString('o');configuration='release / RelWithDebInfo / -O2 -fno-fast-math -ffp-contract=off';compiler='clang 23.1.2';checkout=$taskRoot;pack='Embedded game_pack.c; no external pack';purpose='Immutable tested optimized inputs for paired CPU4 measurement';files=$taskFiles} | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $taskOutput 'metadata.json') -Encoding utf8
Write-Output "Preserved optimized snapshot: $taskOutput"
